const express = require('express');
const { AnalyticsRpcClient } = require('@repo/analytics-client');
const { requireUserSession } = require('./session');
const { Project } = require('./models');

const app = express();

const analyticsClient = new AnalyticsRpcClient({
  endpoint: 'http://clickhouse-gateway.internal:7100',
  sharedToken: process.env.ANALYTICS_SERVICE_TOKEN
});

app.get('/api/analytics/heatmaps', requireUserSession, async (req, res) => {
  const { projectId, pagePath, timeRange } = req.query;

  // Validate that the projectId belongs to the authenticated user's organization
  const project = await Project.findOne({
    where: {
      id: projectId,
      organizationId: req.user.organizationId
    }
  });

  if (!project) {
    return res.status(404).json({ error: 'Project not found or access denied' });
  }

  const heatmapData = await analyticsClient.fetchClickHeatmap({
    projectId: project.id,
    path: pagePath,
    range: timeRange || '24h'
  });

  res.json({ points: heatmapData.dataPoints });
});

app.listen(8085);
